import{c as a,Q as e,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const d="/assets/DataCopyGatherB.CfmTtiR6.png",g=JSON.parse('{"title":"GatherB","description":"","frontmatter":{},"headers":[{"level":1,"title":"GatherB","slug":"gatherb"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"定义原型","slug":"定义原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Reg矢量计算/离散与聚合/GatherB.md","filePath":"api/SIMD-API/基础API/Reg矢量计算/离散与聚合/GatherB.md"}'),l={name:"api/SIMD-API/基础API/Reg矢量计算/离散与聚合/GatherB.md"};function r(i,t,p,o,c,h){return e(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="gatherb" tabindex="-1">GatherB <a class="header-anchor" href="#gatherb" aria-label="Permalink to &quot;GatherB&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>给定源操作数在UB中的基地址和索引，GatherB指令根据索引位置将源操作数按DataBlock收集到结果寄存器张量中。每个DataBlock长度为32Byte。收集过程如下图所示：</p><p><img src="'+d+`" alt=""></p><h2 id="定义原型" tabindex="-1">定义原型 <a class="header-anchor" href="#定义原型" aria-label="Permalink to &quot;定义原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T = DefaultType, typename U, typename S&gt;</span></span>
<span class="line"><span>__simd_callee__ inline void GatherB(U&amp; dstReg, __ubuf__ T* baseAddr, S&amp; index, MaskReg&amp; mask)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>目的操作数和源操作数的数据类型</td></tr><tr><td>U</td><td>目的操作数的RegTensor类型， 例如RegTensor&lt;half&gt;，由编译器自动推导，用户不需要填写</td></tr><tr><td>S</td><td>索引值的RegTensor类型，例如RegTensor&lt;uint32_t&gt;，由编译器自动推导，用户不需要填写</td></tr></tbody></table><p><strong>表 2</strong> 函数参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstReg</td><td>输出</td><td>目的操作数。 类型为RegTensor Ascend 950PR/Ascend 950DT，dstReg/baseAddr支持的数据类型为：uint8_t/int8_t/uint16_t/int16_t/uint32_t/int32_t/half/float/bfloat16_t/uint64_t/int64_t</td></tr><tr><td>baseAddr</td><td>输入</td><td>源操作数在UB中的基地址。需要32B对齐。 类型为UB指针。 Ascend 950PR/Ascend 950DT，支持的数据类型为：uint8_t/int8_t/uint16_t/int16_t/uint32_t/int32_t/half/float/bfloat16_t/uint64_t/int64_t</td></tr><tr><td>index</td><td>输入</td><td>dstReg中的每个DataBlock在UB中相对于baseAddr的索引位置。索引位置要大于等于0且32B对齐。 类型为RegTensor Ascend 950PR/Ascend 950DT，支持的数据类型为：uint32_t</td></tr><tr><td>mask</td><td>输入</td><td>src element操作有效指示，详细说明请参考MaskReg</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>目的操作数与源操作数的数据类型相同。</li><li>源操作数在UB中的基地址需要32B对齐。</li><li>索引位置要大于等于0且32B对齐。</li><li>索引寄存器中可以存在相同的值，即可以多次读取源操作数中同一个DataBlock的数据。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;typename T, typename U&gt;</span></span>
<span class="line"><span>__simd_vf__ inline void GatherBVF(__ubuf__ T* dstAddr, __ubuf__ T* src0Addr, __ubuf__ U* src1Addr, uint32_t count, uint32_t oneRepeatSize, uint16_t repeatTimes)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;U&gt; srcReg;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; dstReg;</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg mask;    </span></span>
<span class="line"><span>    for (uint16_t i = 0; i &lt; repeatTimes; i++) {</span></span>
<span class="line"><span>        mask = AscendC::Reg::UpdateMask&lt;T&gt;(count);</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg, src1Addr + i * oneRepeatSize);</span></span>
<span class="line"><span>        AscendC::Reg::GatherB(dstReg, src0Addr, srcReg, mask);</span></span>
<span class="line"><span>        AscendC::Reg::StoreAlign(dstAddr + i * oneRepeatSize, dstReg, mask);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,17)])])}const u=a(l,[["render",r]]);export{g as __pageData,u as default};
